//! Statistics kernel against SciPy reference vectors
//! (generated by `scripts/stats-reference.py`).

#![allow(clippy::unwrap_used, clippy::expect_used)]

use prova_core::stats::{hodges_lehmann, holm, mann_whitney};
use serde_json::Value;

fn reference() -> Value {
    serde_json::from_str(include_str!("stats_reference.json")).unwrap()
}

fn floats(v: &Value) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap())
        .collect()
}

#[test]
fn mann_whitney_matches_scipy() {
    for c in reference()["mann_whitney"].as_array().unwrap() {
        let (x, y) = (floats(&c["x"]), floats(&c["y"]));
        let r = mann_whitney(&x, &y);
        assert_eq!(r.method, c["method"].as_str().unwrap(), "{c}");
        assert!(
            (r.u - c["u"].as_f64().unwrap()).abs() < 1e-9,
            "U {} vs {c}",
            r.u
        );
        let p = c["p"].as_f64().unwrap();
        assert!((r.p - p).abs() < 1e-6, "p {} vs {p} for {c}", r.p);
    }
}

#[test]
fn hodges_lehmann_interval_matches_reference() {
    let mut checked = 0;
    for c in reference()["mann_whitney"].as_array().unwrap() {
        let Some(hl) = c.get("hl") else { continue };
        let s = hodges_lehmann(&floats(&c["x"]), &floats(&c["y"]), 0.05);
        for (got, key) in [
            (s.estimate, "estimate"),
            (s.lower, "lower"),
            (s.upper, "upper"),
        ] {
            let want = hl[key].as_f64().unwrap();
            assert!((got - want).abs() < 1e-9, "{key}: {got} vs {want} for {c}");
        }
        checked += 1;
    }
    assert!(checked >= 10);
}

#[test]
fn holm_matches_definition() {
    let r = reference();
    let got = holm(&floats(&r["holm"]["p"]));
    let want = floats(&r["holm"]["adjusted"]);
    for (g, w) in got.iter().zip(&want) {
        assert!((g - w).abs() < 1e-12);
    }
}
